llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C42"],
      "claim": "Verapamil, a structurally related dimethoxyphenyl tertiary amine, showed absolute oral bioavailability of 52.3% in cirrhotic patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Praziquantel, a chiral tetrahydroisoquinoline-like drug, had oral bioavailability of 27.2% in patients with hepatic cirrhosis, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Noscapine, which shares dimethoxybenzene and N-methylated chiral amine features, had absolute oral bioavailability of 30% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Sulpiride, a basic methoxybenzamide, had absolute oral bioavailability of about 34%, supporting F ≥ 20% despite polar/labile features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Encainide, a methoxybenzamide with a basic amine, showed mean oral bioavailability of 30% in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Alfentanil, a basic amide/piperidine drug, had baseline oral bioavailability of 37% in healthy volunteers, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Levosulpiride, a basic methoxybenzamide with a pyrrolidine amine, had oral bioavailability of about 30%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "S-verapamil during rifampin co-treatment had very low absolute bioavailability (0.7%), but this reflects strong enzyme induction not applicable to the query condition.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer analogues with shared dimethoxyphenyl, basic amine, and amide/lactam features show absolute oral bioavailability between 23% and 52%, all above the 20% threshold. The low-bioavailability examples are condition-specific (rifampin induction) or low-transfer (aniracetam), and the physicochemical prior is mixed but not disqualifying. Therefore the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the query molecule.",
    "Verapamil evidence is from cirrhotic patients, which may overestimate healthy bioavailability.",
    "Rifampin co-treatment data are not applicable to the query's normal condition.",
    "Metabolic stability and transporter effects for the query are unknown.",
    "Low neutral fraction due to basic pKa may reduce absorption, but similar basic analogues still exceed 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

